create table if not exists public.smollan_project_history (id uuid primary key default gen_random_uuid(),project_name text not null unique,client text,start_date date,end_date date,quotation_reference text,additional_quotation_reference text,po_status text,po_reference text,invoiced_status text,invoice_reference text,payment_date text,amount_paid text,quotation_amount_mad numeric(14,2),actual_cost_mad numeric(14,2),po_amount_mad numeric(14,2),variance_mad numeric(14,2),finance_checked boolean not null default false,invoice_supplier_references text,source_workbook text not null default 'SMOLLAN - Activations Finance Tracker (2).xlsx',source_sheets text[] not null default ARRAY['Quotations & POs','Costs & Invoices'],imported_at timestamptz not null default now());
create index if not exists smollan_project_history_client_idx on public.smollan_project_history(client);
alter table public.smollan_project_history enable row level security;
drop policy if exists smollan_project_history_member_read on public.smollan_project_history;
create policy smollan_project_history_member_read on public.smollan_project_history for select to authenticated using (exists(select 1 from public.smollan_memberships m where m.user_id=auth.uid() and m.is_active));
drop policy if exists smollan_project_history_admin_write on public.smollan_project_history;
create policy smollan_project_history_admin_write on public.smollan_project_history for all to authenticated using (exists(select 1 from public.smollan_memberships m where m.user_id=auth.uid() and m.is_active and m.role in ('platform_admin','leadership','finance'))) with check (exists(select 1 from public.smollan_memberships m where m.user_id=auth.uid() and m.is_active and m.role in ('platform_admin','leadership','finance')));